require_once __DIR__.'/../includes/bootstrap.php';$user=require_login();$error='';$name='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim((string)($_POST['name']??''));if(mb_strlen($name,'UTF-8')<2||mb_strlen($name,'UTF-8')>140)$error='Nama workspace harus 2–140 karakter.';else{$st=$GLOBALS['pdo']->prepare('SELECT COUNT(*) FROM workspace_members WHERE user_id=?');$st->execute([$user['id']]);$count=(int)$st->fetchColumn();$workspace=current_workspace();$limit=plan_limits($workspace)['workspaces'];if($limit!==-1&&$count>=$limit)$error='Paket Free memiliki satu workspace. Ajukan paket Pro untuk membuat workspace tambahan.';else{try{$GLOBALS['pdo']->beginTransaction();$slug=substr(slugify($name),0,140).'-'.bin2hex(random_bytes(4));$GLOBALS['pdo']->prepare('INSERT INTO workspaces(owner_id,name,slug,plan) VALUES(?,?,?,"free")')->execute([$user['id'],$name,$slug]);$id=(int)$GLOBALS['pdo']->lastInsertId();$GLOBALS['pdo']->prepare('INSERT INTO workspace_members(workspace_id,user_id,member_role) VALUES(?,?,"owner")')->execute([$id,$user['id']]);$GLOBALS['pdo']->commit();$_SESSION['workspace_id']=$id;audit_log('workspace.created','workspace',$id);flash('success','Workspace baru dibuat.');redirect('app/index.php');}catch(Throwable $e){if($GLOBALS['pdo']->inTransaction())$GLOBALS['pdo']->rollBack();$error='Workspace belum dapat dibuat.';error_log('Datanix workspace create failed: '.$e->getMessage());}}}}
require_once __DIR__.'/../includes/header.php';$layout='app';datanix_header('Buat workspace','settings',$layout);
